<section class="page-head"><div><p class="eyebrow">Catalog management</p><h1>Products</h1><p class="muted">Manage pricing, availability, variants, and product media.</p></div><a class="button primary" href="/products/create">Add product</a></section>
<form class="filter-bar" method="get" action="/products"><label class="search-field"><span class="sr-only">Search products</span><input type="search" name="q" value="<?= e($filters['q']) ?>" placeholder="Search name, SKU, description"></label><select name="category_id" aria-label="Filter category"><option value="0">All categories</option><?php foreach($categories as$c):?><option value="<?= e($c['id']) ?>" <?= $filters['category_id']==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select><select name="status" aria-label="Filter status"><option value="">All statuses</option><?php foreach(['DRAFT','ACTIVE','ARCHIVED']as$s):?><option <?= $filters['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach ?></select><select name="availability" aria-label="Filter availability"><option value="">Any availability</option><option value="AVAILABLE" <?= $filters['availability']==='AVAILABLE'?'selected':'' ?>>Available</option><option value="UNAVAILABLE" <?= $filters['availability']==='UNAVAILABLE'?'selected':'' ?>>Unavailable</option></select><select name="sort" aria-label="Sort products"><option value="newest" <?= $filters['sort']==='newest'?'selected':'' ?>>Newest</option><option value="oldest" <?= $filters['sort']==='oldest'?'selected':'' ?>>Oldest</option><option value="name" <?= $filters['sort']==='name'?'selected':'' ?>>Name</option><option value="price_low" <?= $filters['sort']==='price_low'?'selected':'' ?>>Price low</option><option value="price_high" <?= $filters['sort']==='price_high'?'selected':'' ?>>Price high</option></select><button class="button secondary">Apply</button></form>
<?php if(!$products):?><section class="empty-state panel"><div class="empty-icon">□</div><h2><?= $filters['q']||$filters['category_id']||$filters['status']||$filters['availability']?'No products match these filters':'Your store is empty' ?></h2><p><?= $filters['q']||$filters['category_id']||$filters['status']||$filters['availability']?'Change or clear the filters to see other products.':'Add your first product to start selling.' ?></p><a class="button <?= $filters['q']||$filters['category_id']||$filters['status']||$filters['availability']?'secondary':'primary' ?>" href="<?= $filters['q']||$filters['category_id']||$filters['status']||$filters['availability']?'/products':'/products/create' ?>"><?= $filters['q']||$filters['category_id']||$filters['status']||$filters['availability']?'Clear filters':'Add first product' ?></a></section><?php else:?><section class="product-admin-grid"><?php foreach($products as$product):?><article class="product-admin-card"><div class="product-thumb"><?php if($product['thumbnail']):?><img src="<?= e($product['thumbnail']) ?>" alt=""><?php else:?><span>No image</span><?php endif ?><span class="badge product-status <?= strtolower($product['status']) ?>"><?= e($product['status']) ?></span></div><div class="product-card-body"><div><p class="product-meta"><?= e($product['category_name']??'Uncategorized') ?><?= $product['sku']?' · '.e($product['sku']):'' ?></p><h2><?= e($product['name']) ?></h2></div><strong class="product-price"><?= e($store['currency_code']) ?> <?= e($product['price']) ?></strong><span class="availability <?= strtolower($product['availability']) ?>"><?= $product['availability']==='AVAILABLE'?'Available':'Unavailable' ?></span><div class="product-actions"><a class="button compact secondary" href="/products/<?= e($product['id']) ?>/edit">Edit</a><form method="post" action="/products/<?= e($product['id']) ?>/duplicate"><?= csrf_field() ?><button class="button compact ghost">Duplicate</button></form><form method="post" action="/products/<?= e($product['id']) ?>/archive" data-confirm="Archive product?" data-confirm-message="The product will remain saved but unavailable to customers."><?= csrf_field() ?><button class="button compact ghost">Archive</button></form><form method="post" action="/products/<?= e($product['id']) ?>/delete" data-confirm="Delete product?" data-confirm-message="This removes the product from catalog management. Historical orders will preserve snapshots in Phase 4."><?= csrf_field() ?><button class="button compact danger-ghost">Delete</button></form></div></div></article><?php endforeach ?></section><?php if($pagination['pages']>1):?><?php $query=$filters;unset($query['page']);?><nav class="pagination" aria-label="Product pages"><?php if($pagination['page']>1):?><a class="button secondary" href="/products?<?= e(http_build_query($query+['page'=>$pagination['page']-1])) ?>">Previous</a><?php endif ?><span>Page <?= e($pagination['page']) ?> of <?= e($pagination['pages']) ?> · <?= e($pagination['total']) ?> products</span><?php if($pagination['page']<$pagination['pages']):?><a class="button secondary" href="/products?<?= e(http_build_query($query+['page'=>$pagination['page']+1])) ?>">Next</a><?php endif ?></nav><?php endif ?><?php endif ?>
